class Solution {
public:
    int countSubmatrices(vector<vector<int>>& grid, int k) {
        int m = grid.size();
        int n = grid[0].size();
        vector<long long> colsum(n, 0);
        int ans = 0;
        for (int i = 0; i < m; i++) {
            long long running = 0;
            for (int j = 0; j < n; j++) {
                colsum[j] += grid[i][j];
                running += colsum[j];
                if (running <= k) ans++;
            }
        }
        return ans;
    }
};
